<?php
namespace App\Http\Controllers;
use App\Services\StudioContent;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class StudioController extends Controller {
 public function __construct(private StudioContent $content) {}
 public function publicContent(){ return response()->json($this->content->read(true)); }
 public function content(Request $r){ return response()->json(['content'=>$this->content->read(),'storage'=>['driver'=>DB::connection()->getDriverName(),'label'=>DB::connection()->getDriverName()==='sqlsrv'?'SQL Server':'Laravel database'],'users'=>$r->user()->role === 'owner' ? User::all()->map->dto():[]]); }
 public function save(Request $r,string $collection){ $v=$r->validate(['item'=>'required|array','revision'=>'required|integer|min:1']); $item=$this->content->validate($collection,$v['item']); return $this->content->mutate($v['revision'],function($data) use($collection,$item){ $items=$data[$collection] ?? []; $index=array_search($item['id'],array_column($items,'id'),true); if($index===false) $items[]=$item; else $items[$index]=$item; $data[$collection]=$items; return $data; }); }
 public function delete(Request $r,string $collection,string $id){ abort_unless(in_array($collection,StudioContent::COLLECTIONS),404); $v=$r->validate(['revision'=>'required|integer']); return $this->content->mutate($v['revision'],function($data) use($collection,$id){ $data[$collection]=array_values(array_filter($data[$collection] ?? [],fn($i)=>$i['id'] !== $id)); return $data; }); }
 public function settings(Request $r){ $v=$r->validate(['settings'=>'required|array','revision'=>'required|integer']); return $this->content->mutate($v['revision'],function($data) use($v){ foreach($v['settings'] as $key=>$value){ abort_unless(array_key_exists($key,$data['settings']) && is_string($value) && mb_strlen($value)<=5000,422,'Invalid page setting.'); if($key==='logo') $this->content->image($value); if($key==='defaultTheme') abort_unless(in_array($value,['light','dark']),422); if($key==='contactEmail' && $value!=='') abort_unless(filter_var($value,FILTER_VALIDATE_EMAIL),422); $data['settings'][$key]=$value; } return $data; }); }
 public function inquiries(){ return DB::table('studio_inquiries')->orderByDesc('created_at')->get()->map(fn($r)=>['id'=>$r->id,'name'=>$r->name,'email'=>$r->email,'company'=>$r->company,'service'=>$r->service,'message'=>$r->message,'receivedAt'=>$r->created_at]); }
 public function contact(Request $r){ $v=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:254','company'=>'nullable|string|max:150','service'=>'required|in:'.implode(',',StudioContent::SERVICES),'message'=>'required|string|min:10|max:5000','website'=>'nullable|string|max:0']); unset($v['website']); $v['company']=$v['company'] ?? ''; DB::table('studio_inquiries')->insert($v+['id'=>(string)Str::uuid(),'created_at'=>now(),'updated_at'=>now()]); return response()->json(['success'=>true],201); }
 public function upload(Request $r){ $v=$r->validate(['data'=>'required|string|max:7000000']); abort_unless(preg_match('~^data:image/(png|jpeg|webp);base64,(.+)$~s',$v['data'],$m),422,'Upload PNG, JPEG or WebP.'); $bytes=base64_decode($m[2],true); abort_unless($bytes!==false && strlen($bytes)<=5000000,422,'Image must be under 5 MB.'); $info=@getimagesizefromstring($bytes); abort_unless($info && in_array($info['mime'],['image/png','image/jpeg','image/webp']) && $info[0]<=10000 && $info[1]<=10000,422,'Invalid image.'); $ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$info['mime']]; $name=Str::uuid().'.'.$ext; \Illuminate\Support\Facades\Storage::disk('public')->put('uploads/'.$name,$bytes); return response()->json(['url'=>'/uploads/'.$name],201); }
}
